/* @lc app=leetcode id=3885 lang=kotlin */ class EventManager(events: Array<IntArray>, val m: HashMap<Int, Int> = HashMap(), val ts: java.util.TreeSet<Long> = java.util.TreeSet(), val init: Unit = events.forEach { e -> m.put(e[0], e[1]).let { ts.add((e[1].toLong() shl 30) or ((1L shl 30) - 1 - e[0])) } }) { fun updatePriority(eventId: Int, newPriority: Int) { ts.remove((m[eventId]!!.toLong() shl 30) or ((1L shl 30) - 1 - eventId)).let { m.put(eventId, newPriority) }.let { ts.add((newPriority.toLong() shl 30) or ((1L shl 30) - 1 - eventId)) } } fun pollHighest(): Int = ts.pollLast()?.let { k -> ((1L shl 30) - 1 - (k and ((1L shl 30) - 1))).toInt().also { m.remove(it) } } ?: -1 }